shellCommands.command:
/bin/bash -lc "cat > /tmp/stroka-browser-check/check.mjs <<'EOF'
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1080}});
const errors=[];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5174');
await page.evaluate(() => document.fonts.ready);
await page.screenshot({path:'/tmp/stroka-desktop.png',fullPage:true});
console.log('Initial dimensions:', await page.locator('.editor-frame').boundingBox());
const source=page.locator('#markdown-content');
const preview=page.getByRole('article',{name:'Предпросмотр Markdown'});
await source.fill('# Проверка\\n\\n**Жирный** и *курсив*\\n\\n- пункт\\n\\n> Цитата\\n\\n[Ссылка](https://example.com)\\n\\n~~убрать~~\\n\\n- [x] Сделано\\n\\n| А | Б |\\n| --- | --- |\\n| 1 | 2 |\\n\\n"'```js'"\\nconst x = 1;\\n"'```'"');
assert.equal(await preview.locator('h1').textContent(),'Проверка');
assert.equal(await preview.locator('strong').textContent(),'Жирный');
assert.equal(await preview.locator('em').textContent(),'курсив');
assert.equal(await preview.locator('blockquote').textContent(),'\\nЦитата\\n');
assert.equal(await preview.locator('a').getAttribute('href'),'https://example.com');
assert.equal(await preview.locator('del').textContent(),'убрать');
assert.equal(await preview.locator('table').count(),1);
assert.equal(await preview.locator('input[type=\"checkbox\"]:checked').count(),1);
assert.equal(await preview.locator('pre code').textContent(),'const x = 1;\\n');
await source.fill('<script>window.markdownExecuted = true</script>\\n\\n[unsafe](javascript:alert(1))');
assert.equal(await preview.locator('script').count(),0);
assert.equal(await page.evaluate(()=>window.markdownExecuted),undefined);
assert.notEqual(await preview.locator('a').getAttribute('href'),'javascript:alert(1)');
await source.fill('Выделенный текст');
await source.evaluate(el=>el.setSelectionRange(0,10));
await page.getByRole('button',{name:'Жирный (Ctrl+B)',exact:true}).click();
assert.equal(await source.inputValue(),'**Выделенный** текст');
await source.fill('курсив');
await source.selectText();
await page.keyboard.press('Control+i');
assert.equal(await source.inputValue(),'*курсив*');
await page.getByRole('button',{name:'Только предпросмотр',exact:true}).click();
assert.equal(await source.count(),0);
assert.equal(await preview.locator('em').textContent(),'курсив');
await page.getByRole('button',{name:'Редактор и предпросмотр',exact:true}).click();
await source.fill('');
assert.equal(await preview.getByText('Здесь появится ваш текст').count(),1);
await page.getByRole('button',{name:'Готово',exact:true}).click();
assert.equal(await page.getByRole('alert').textContent(),'Напишите текст публикации');
await source.fill('# Сохранённый текст\\n\\n**Содержимое черновика**');
await page.locator('#publication-title').fill('Тестовый черновик');
await page.getByRole('button',{name:'Сохранить черновик',exact:true}).click();
await page.reload();
assert.equal(await page.locator('#publication-title').inputValue(),'Тестовый черновик');
assert.equal(await source.inputValue(),'# Сохранённый текст\\n\\n**Содержимое черновика**');
await page.getByRole('button',{name:/Мои черновики/}).click();
assert.equal(await page.locator('.draft-item strong').textContent(),'Тестовый черновик');
await page.getByRole('button',{name:'Закрыть',exact:true}).click();
await page.getByRole('button',{name:'Шпаргалка по Markdown',exact:true}).click();
assert.equal(await page.locator('.cheatsheet>div').count(),12);
await page.keyboard.press('Escape');
await page.getByRole('button',{name:'Готово',exact:true}).click();
assert.equal(await page.locator('.document-dialog h2').textContent(),'Тестовый черновик');
const downloaded = page.waitForEvent('download');
await page.getByRole('button',{name:'Скачать .md',exact:true}).click();
assert.equal((await downloaded).suggestedFilename(),'Тестовый черновик.md');
await page.getByRole('button',{name:'Закрыть',exact:true}).click();
for(const width of [390,768,1024]) {
  await page.setViewportSize({width,height:844});
  const dimensions=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth}));
  assert.ok(dimensions.scroll<=dimensions.width,"'`Overflow at ${width}: ${dimensions.scroll}`);
}
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'"'/tmp/stroka-mobile.png',fullPage:true});
assert.deepEqual(errors,[]);
console.log('PASS: live Markdown, GFM, safe rendering, selection formatting, keyboard shortcuts, view switching, validation, draft persistence, help, download and responsive layout.');
await browser.close();
EOF
npx --yes prettier --write src/App.tsx src/styles.css index.html"
